"""Checks entries regenerated by tools/generator/generate.mjs against the committed corpus.

Bytes cannot match: the regenerated entry has fresh keys, other sequence numbers and close times,
and possibly another network passphrase. What must match is everything that does not depend on
those. For each regenerated entry this script checks, and prints as MATCH, SKIP (with the reason)
or DIFF:

  1. every file decodes and re-encodes byte-identical with rs-stellar-xdr 30.0.0 (xdr-roundtrip),
     and its sha256 matches capture.json;
  2. the LedgerCloseMeta is v2 at protocol 30, applies the transaction, and its copies of the
     envelope, result and meta are the ones in the entry files;
  3. the transaction hash recomputed from the envelope under the run's passphrase equals the hash
     core applied, and does not under the other passphrase: the entry is bound to that network;
  4. each expected value in the manifest (tools/build_manifest.py SPEC): literals are compared
     with the committed value; values taken from capture.json ("@key") depend on generated keys,
     so they are skipped against the committed entry, checked against the regenerated
     capture.json, and replaced by the key-independent properties listed in DERIVED;
  5. envelope, result and meta have the same shape as the committed files (same keys, union arms
     and array lengths), and every leaf value is equal unless it is explained by a generated key,
     a ledger sequence or time, or the network id. Each explained difference is counted by reason;
     any other difference is a DIFF.

Usage: python tools/generator/compare.py [--out tools/generator/out] [--json REPORT]
Exit status 1 if any check is DIFF or no regenerated entry is found.
"""
import argparse
import base64
import hashlib
import json
import re
import subprocess
import sys
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "tools"))
from build_manifest import RT, SPEC, XDR_TYPES, pointer  # noqa: E402

PASSPHRASES = {"testnet": "Test SDF Network ; September 2015",
               "mainnet": "Public Global Stellar Network ; September 2015"}
PROTOCOL = 30
U64_MAX = 18446744073709551615


# ---------- XDR and strkey helpers ----------

def rt(xdr_type, path, as_json=False):
    out = subprocess.run([str(RT), xdr_type, str(path)] + (["--json"] if as_json else []),
                         capture_output=True, text=True, check=False)
    return json.loads(out.stdout)


def crc16_xmodem(data):
    crc = 0
    for b in data:
        crc ^= b << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) if crc & 0x8000 else crc << 1
            crc &= 0xFFFF
    return crc


def strkey(s):
    """Returns (version letter, payload bytes) of a SEP-23 strkey, checking its CRC."""
    raw = base64.b32decode(s + "=" * (-len(s) % 8))
    body, crc = raw[:-2], int.from_bytes(raw[-2:], "little")
    if crc16_xmodem(body) != crc:
        raise ValueError(f"bad strkey checksum: {s}")
    return chr(ord("A") + (body[0] >> 3)), body[1:]


def g_address(key32):
    body = bytes([6 << 3]) + key32
    return base64.b32encode(body + crc16_xmodem(body).to_bytes(2, "little")).decode()


def muxed(s):
    """M... strkey -> (G... base account, muxed id)."""
    v, p = strkey(s)
    assert v == "M" and len(p) == 40, s
    return g_address(p[:32]), int.from_bytes(p[32:], "big")


def signed_payload(s):
    """P... strkey -> (G... signer account, payload bytes)."""
    v, p = strkey(s)
    assert v == "P", s
    n = int.from_bytes(p[32:36], "big")
    return g_address(p[:32]), p[36:36 + n]


def tx_hash(envelope_b64, envelope_json, passphrase):
    """sha256(network id || ENVELOPE_TYPE_TX || Transaction) for a v1 envelope."""
    raw = base64.b64decode(envelope_b64)
    if "tx" not in envelope_json or int.from_bytes(raw[:4], "big") != 2:
        raise ValueError("only ENVELOPE_TYPE_TX envelopes are supported")
    sigs = envelope_json["tx"]["signatures"]
    sig_len = 4 + sum(8 + len(bytes.fromhex(s["signature"])) + (-len(bytes.fromhex(s["signature"])) % 4)
                      for s in sigs)
    tx = raw[4:len(raw) - sig_len]
    network_id = hashlib.sha256(passphrase.encode()).digest()
    return hashlib.sha256(network_id + (2).to_bytes(4, "big") + tx).hexdigest()


# ---------- key-independent properties that replace "@key" expected values ----------

def cap40_derived(env, meta, committed_env, committed_meta):
    ptr = "/v4/operations/0/changes/1/updated/data/account/signers/0/key"
    got, want = pointer(meta, ptr), pointer(committed_meta, ptr)
    (g_acct, g_payload), (_, w_payload) = signed_payload(got), signed_payload(want)
    return [
        ("signer key type is signed payload (P... strkey)", strkey(got)[0], strkey(want)[0]),
        ("signed payload length", len(g_payload), len(w_payload)),
        ("signed payload bytes (hex)", g_payload.hex(), w_payload.hex()),
        ("signer's ed25519 key is the transaction source account",
         g_acct == env["tx"]["tx"]["source_account"], signed_payload(want)[0] == committed_env["tx"]["tx"]["source_account"]),
    ]


def cap27_derived(env, meta, committed_env, committed_meta):
    def view(e, m):
        src_base, src_id = muxed(e["tx"]["tx"]["source_account"])
        dst_base, dst_id = muxed(e["tx"]["tx"]["operations"][0]["body"]["payment"]["destination"])
        topics = m["v4"]["operations"][0]["events"][0]["body"]["v0"]["topics"]
        return {"src_type": strkey(e["tx"]["tx"]["source_account"])[0], "src_id": src_id,
                "dst_type": strkey(e["tx"]["tx"]["operations"][0]["body"]["payment"]["destination"])[0],
                "dst_id": dst_id,
                "event_from_is_source_base": topics[1]["address"] == src_base,
                "event_to_is_destination_base": topics[2]["address"] == dst_base}
    g, w = view(env, meta), view(committed_env, committed_meta)
    return [
        ("transaction source is a muxed account (M... strkey)", g["src_type"], w["src_type"]),
        ("muxed source id (u64 max)", g["src_id"], w["src_id"]),
        ("payment destination is a muxed account (M... strkey)", g["dst_type"], w["dst_type"]),
        ("muxed destination id (zero)", g["dst_id"], w["dst_id"]),
        ("transfer event topic 1 is the source's base G account", g["event_from_is_source_base"], w["event_from_is_source_base"]),
        ("transfer event topic 2 is the destination's base G account", g["event_to_is_destination_base"], w["event_to_is_destination_base"]),
    ]


DERIVED = {"cap40-signed-payload-signer-max-payload": cap40_derived,
           "cap27-muxed-source-and-destination-id-extremes": cap27_derived}

# ---------- shape and leaf comparison ----------

STRKEY = re.compile(r"^[GMP][A-Z2-7]{55,}$")
CONTRACT = re.compile(r"^C[A-Z2-7]{55}$")
HEX = re.compile(r"^[0-9a-f]+$")
LEDGER_TIME_FIELDS = {"last_modified_ledger_seq", "seq_ledger", "seq_time", "seq_num", "max_time", "min_time",
                      "ledger_seq", "close_time", "live_until_ledger_seq"}


def explain(path, a, b):
    """Why two differing leaves are allowed to differ, or None."""
    field = path.rsplit("/", 1)[-1]
    if field in LEDGER_TIME_FIELDS:
        return "ledger sequence or time"
    if isinstance(a, str) and isinstance(b, str):
        if STRKEY.match(a) and STRKEY.match(b):
            return "generated key"
        if CONTRACT.match(a) and CONTRACT.match(b):
            return "contract id (derives from the network id)"
        if field == "signature" and HEX.match(a) and HEX.match(b) and len(a) == len(b):
            return "signature by a generated key"
        if field == "hint" and HEX.match(a) and HEX.match(b) and len(a) == len(b) == 8:
            return "signature hint (last 4 bytes of a generated key)"
    return None


def walk(a, b, path, shape_diffs, leaf_diffs, explained):
    if isinstance(a, dict) and isinstance(b, dict):
        if a.keys() != b.keys():
            shape_diffs.append(f"{path or '/'}: keys {sorted(a)} vs committed {sorted(b)}")
            return
        for k in a:
            walk(a[k], b[k], f"{path}/{k}", shape_diffs, leaf_diffs, explained)
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            shape_diffs.append(f"{path}: {len(a)} items vs committed {len(b)}")
            return
        for i, (x, y) in enumerate(zip(a, b)):
            walk(x, y, f"{path}/{i}", shape_diffs, leaf_diffs, explained)
    elif type(a) is not type(b) or isinstance(a, (dict, list)) != isinstance(b, (dict, list)):
        shape_diffs.append(f"{path}: {type(a).__name__} vs committed {type(b).__name__}")
    elif a != b:
        why = explain(path, a, b)
        if why:
            explained[why] += 1
        else:
            leaf_diffs.append(f"{path}: {a!r} vs committed {b!r}")


# ---------- report ----------

class Report:
    def __init__(self):
        self.rows, self.failed = [], 0

    def add(self, network, entry, check, status, detail=""):
        self.rows.append({"network": network, "entry": entry, "check": check, "status": status, "detail": detail})
        self.failed += status == "DIFF"
        print(f"  {status:5} {check}" + (f": {detail}" if detail else ""))

    def eq(self, network, entry, check, got, want):
        self.add(network, entry, check, "MATCH" if got == want else "DIFF",
                 f"{got}" if got == want else f"{got!r} vs committed {want!r}")


def compare_entry(rep, network, d):
    cap = json.loads((d / "capture.json").read_text(encoding="utf-8"))
    eid = cap["id"]
    add = lambda check, status, detail="": rep.add(network, eid, check, status, detail)  # noqa: E731
    eq = lambda check, got, want: rep.eq(network, eid, check, got, want)  # noqa: E731
    committed = ROOT / "corpus" / "entries" / eid
    manifest = next(e for e in json.loads((ROOT / "corpus" / "manifest.json").read_text())["entries"] if e["id"] == eid)
    print(f"\n{network} / {eid}  (tx {cap['txHash'][:16]}..., ledger {cap['ledger']})")

    # 1. byte round trip and hashes
    for f in cap["files"]:
        name = f["path"].rsplit("/", 1)[-1]
        r = rt(f["xdrType"], d / name)
        add(f"{name} decodes and re-encodes byte-identical", "MATCH" if r.get("roundTripIdentical") else "DIFF", f["xdrType"])
        digest = hashlib.sha256(base64.b64decode((d / name).read_text().strip())).hexdigest()
        if digest != f["sha256"]:
            add(f"{name} sha256 matches capture.json", "DIFF", digest)

    gen = {n: rt(XDR_TYPES[n], d / n, as_json=True) for n in XDR_TYPES}
    com = {n: rt(XDR_TYPES[n], committed / n, as_json=True) for n in XDR_TYPES}

    # 2. LedgerCloseMeta
    eq("LedgerCloseMeta variant", next(iter(gen["ledger-close-meta.b64"])), next(iter(com["ledger-close-meta.b64"])))
    lcm = next(iter(gen["ledger-close-meta.b64"].values()))
    clcm = next(iter(com["ledger-close-meta.b64"].values()))
    header, cheader = lcm["ledger_header"]["header"], clcm["ledger_header"]["header"]
    eq("ledger protocol version", header["ledger_version"], manifest["protocolVersion"])
    ext = lambda h: h["scp_value"]["ext"] if isinstance(h["scp_value"]["ext"], str) else next(iter(h["scp_value"]["ext"]))  # noqa: E731
    eq("StellarValue ext arm (CAP-0088 signed close value)", ext(header), ext(cheader))
    eq("LedgerCloseMeta ext", lcm["ext"], clcm["ext"])
    proc = [p for p in lcm["tx_processing"] if p["result"]["transaction_hash"] == cap["txHash"]]
    add("transaction applied in this LedgerCloseMeta", "MATCH" if len(proc) == 1 else "DIFF",
        f"1 of {len(lcm['tx_processing'])} transactions in ledger {header['ledger_seq']}")
    if len(proc) == 1:
        add("LCM tx_apply_processing equals meta.b64", "MATCH" if proc[0]["tx_apply_processing"] == gen["meta.b64"] else "DIFF")
        add("LCM transaction result equals result.b64", "MATCH" if proc[0]["result"]["result"] == gen["result.b64"] else "DIFF")
        add("envelope.b64 is in the LCM tx set", "MATCH" if json.dumps(gen["envelope.b64"]) in json.dumps(lcm["tx_set"]) else "DIFF")
    eq("TransactionMeta version", next(iter(gen["meta.b64"])), next(iter(com["meta.b64"])))

    # 3. passphrase binding
    env_b64 = (d / "envelope.b64").read_text().strip()
    own = PASSPHRASES[network]
    other = [p for n, p in PASSPHRASES.items() if n != network][0]
    add(f'tx hash recomputed under "{own}" equals the applied hash',
        "MATCH" if tx_hash(env_b64, gen["envelope.b64"], own) == cap["txHash"] else "DIFF")
    add(f'tx hash under "{other}" does not', "MATCH" if tx_hash(env_b64, gen["envelope.b64"], other) != cap["txHash"] else "DIFF")
    if cap["network"]["passphrase"] != own:
        add("capture.json passphrase", "DIFF", cap["network"]["passphrase"])

    # 4. manifest expected values
    spec = SPEC[eid]
    target = gen[spec["expected_file"]]
    for ptr, want, _note in spec["values"]:
        try:
            got = pointer(target, ptr)
        except (KeyError, IndexError, TypeError):
            add(f"expected {ptr}", "DIFF", "pointer does not resolve in the regenerated file")
            continue
        if isinstance(want, str) and want.startswith("@"):
            key = want[1:]
            add(f"expected {ptr}", "SKIP", f"depends on generated keys (capture.json {key}); "
                f"regenerated value {'equals' if got == cap.get(key) else 'DOES NOT equal'} its own capture.json")
            if got != cap.get(key):
                add(f"expected {ptr} equals regenerated capture.json {key}", "DIFF", f"{got!r} vs {cap.get(key)!r}")
        else:
            eq(f"expected {ptr}", got, want)
    try:
        derived = DERIVED.get(eid, lambda *a: [])(gen["envelope.b64"], gen["meta.b64"], com["envelope.b64"], com["meta.b64"])
    except (KeyError, IndexError, TypeError, AssertionError, ValueError) as e:
        derived = []
        add("key-independent properties", "DIFF", f"cannot be read from the regenerated entry ({type(e).__name__}: {e})")
    for check, got, want in derived:
        eq(check, got, want)

    # 5. shape and leaves
    for name in ("envelope.b64", "result.b64", "meta.b64"):
        shape, leaves, explained = [], [], Counter()
        walk(gen[name], com[name], "", shape, leaves, explained)
        add(f"{name} shape (keys, union arms, array lengths) equals committed", "DIFF" if shape else "MATCH",
            "; ".join(shape[:5]))
        detail = ", ".join(f"{n} {why}" for why, n in sorted(explained.items())) or "all leaves equal"
        add(f"{name} leaf values equal committed, except explained", "DIFF" if leaves else "MATCH",
            "; ".join(leaves[:5]) if leaves else f"skipped: {detail}")


def main():
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--out", type=Path, default=ROOT / "tools" / "generator" / "out")
    ap.add_argument("--json", type=Path, help="write the full report as JSON")
    args = ap.parse_args()
    rep = Report()
    dirs = sorted(p.parent for p in args.out.glob("*/*/capture.json"))
    for d in dirs:
        compare_entry(rep, d.parent.name, d)
    counts = Counter(r["status"] for r in rep.rows)
    entries = sorted({(r["network"], r["entry"]) for r in rep.rows})
    print(f"\n{len(entries)} regenerated entries: {counts['MATCH']} MATCH, {counts['SKIP']} SKIP, {counts['DIFF']} DIFF")
    if args.json:
        args.json.write_text(json.dumps({"entries": [list(e) for e in entries], "rows": rep.rows}, indent=2) + "\n")
    if rep.failed or not dirs:
        sys.exit(1)


if __name__ == "__main__":
    main()
